/**
 * Get available spells for an item slot
 */
export function getItemSpells(itemBaseId, slotType) {
  const mapping = ITEM_SPELLS_MAP[itemBaseId];
  if (!mapping) return [];
  
  const spellIds = mapping[slotType] || [];
  return spellIds.map(id => ALBION_SPELLS[id]).filter(Boolean);
}
